declare(strict_types=1);session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();$role=(string)($_SESSION['role']??'');if(!in_array($role,['admin','director','sub_director','headteacher','bursar'],true)){http_response_code(403);exit('Your role cannot reconcile school payments.');}$uid=(int)$_SESSION['user_id'];$db=db();$q=$db->prepare('SELECT s.id,s.name FROM schools s JOIN school_memberships m ON m.school_id=s.id WHERE m.user_id=? ORDER BY s.name');$q->execute([$uid]);$schools=$q->fetchAll();if(!$schools){http_response_code(403);exit('No school is linked to your account.');}$ids=array_map('intval',array_column($schools,'id'));$school=(int)($_GET['school_id']??$ids[0]);if(!in_array($school,$ids,true)){http_response_code(403);exit('That school is outside your access.');}$schoolName='School';foreach($schools as $s)if((int)$s['id']===$school)$schoolName=$s['name'];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payment reconciliation · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script><script defer src="assets/api.js"></script><script defer src="assets/fee-reconciliation.js"></script></head><body><div class="app-shell"><?php require __DIR__.'/sidebar.php';?><main class="main-area"><header class="topbar"><div class="crumb">School finance <span>/</span> Payment reconciliation</div><div class="top-actions"><span class="role-chip"><?=e(str_replace('_',' ',$role))?></span></div></header><div class="page-content" data-reconciliation data-api="api/fee_reconciliation.php" data-school="<?=$school?>" data-csrf="<?=e(csrf_token())?>"><section class="welcome-row"><div><div class="eyebrow">SCHOOL FINANCE</div><h1>Payment reconciliation</h1><p class="muted"><?=e($schoolName)?> · Compare bank statement credits with recorded pupil receipts.</p></div><?php if(count($schools)>1):?><form method="get"><label for="reconcile-school">School</label><select id="reconcile-school" name="school_id" onchange="this.form.submit()"><?php foreach($schools as $s):?><option value="<?=$s['id']?>"<?=(int)$s['id']===$school?' selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></form><?php endif;?><a class="button" href="accounting.php?school_id=<?=$school?>">Fee accounts</a></section><div data-reconciliation-message aria-live="polite"></div><section class="note-create"><div class="section-heading"><div><div class="eyebrow">IMPORT STATEMENT</div><h2>Review receipts from a CSV</h2><p class="muted">Required columns: date, amount, reference. Optional: description. Use YYYY-MM-DD or DD/MM/YYYY dates. Importing never posts or changes payments.</p></div></div><form data-reconciliation-import><div class="form-grid"><div><label for="statement-name">Statement name</label><input id="statement-name" name="statement_name" maxlength="180" required></div><div><label for="statement-date">Statement date</label><input id="statement-date" name="statement_date" type="date" required></div><div><label for="statement-csv">CSV file</label><input id="statement-csv" name="statement_csv" type="file" accept=".csv,text/csv" required></div></div><button class="button primary" type="submit">Import and match receipts</button></form></section><section class="content-section"><div class="section-heading"><div><div class="eyebrow">STATEMENT HISTORY</div><h2>Reconciliation batches</h2></div></div><div data-reconciliation-batches><p class="muted">Loading statements…</p></div></section><section class="content-section" data-reconciliation-detail hidden></section></div></main></div><dialog id="reconciliation-match-dialog" class="subject-dialog"><form method="dialog"><div class="subject-dialog-head"><div><div class="eyebrow">MATCH RECEIPT</div><h2>Choose the ledger payment</h2><p class="muted" data-match-summary></p></div><button type="button" class="icon-button" data-close-match aria-label="Close">×</button></div><div class="subject-dialog-body"><label for="match-candidate">Matching payment</label><select id="match-candidate"><option value="">Choose payment</option></select><div class="planning-actions"><button type="button" class="button primary" id="confirm-match">Save match</button><button type="button" class="button" data-close-match>Cancel</button></div></div></form></dialog></body></html>
